-- Slovak product names and descriptions (cat-texts): translations of Czech/Romanian/English feed text,
-- typo fixes and the two duplicate Malfini names. Keyed by supplier reference; each row only changes when
-- the text is still exactly the feed's (COLLATE utf8mb4_bin), so BO edits stay. The URL slug follows a renamed
-- product only while it is still the one generated from the old name.

UPDATE ps_product_lang pl
JOIN ps_lang l ON l.id_lang = pl.id_lang AND l.iso_code = 'sk'
JOIN ps_product p ON p.id_product = pl.id_product
JOIN (
  SELECT '1E1' AS ref, 'Classic - Tričko unisex' AS old_name, 'Classic - Tričko unisex, limitovaná edícia' AS new_name, 'classic-tricko-unisex' AS old_slug, 'classic-tricko-unisex-limitovana-edicia' AS new_slug
  UNION ALL SELECT '95X', 'Bamboo Towel - Uterák unisex', 'Bamboo Towel Premium - Uterák unisex', 'bamboo-towel-uterak-unisex', 'bamboo-towel-premium-uterak-unisex'
  UNION ALL SELECT 'AP731279', 'Nákupná taška z recykovaného materiálu Dekrox', 'Nákupná taška z recyklovaného materiálu Dekrox', 'nakupna-taska-z-recykovaneho-materialu-dekrox', 'nakupna-taska-z-recyklovaneho-materialu-dekrox'
