SET pl.link_rewrite = IF(pl.link_rewrite COLLATE utf8mb4_bin = t.old_slug COLLATE utf8mb4_bin, t.new_slug, pl.link_rewrite),
    pl.name = t.new_name
WHERE pl.name COLLATE utf8mb4_bin = t.old_name COLLATE utf8mb4_bin;

UPDATE ps_product_lang pl
JOIN ps_lang l ON l.id_lang = pl.id_lang AND l.iso_code = 'sk'
JOIN ps_product p ON p.id_product = pl.id_product
JOIN (
  SELECT 'B32' AS ref, 'bezpečnostní obuv S2, ochranná ocelová kaple, protipropichová ocelová stélka, Tunnel system®, E - absorpce energie v oblasti paty, SRA - protiskluzová podešev - duální PU, CI, HI - izolující chlad i teplo, FO - odolná palivovému oleji, A - antistatická, ESD - odvádí elektrostatický náboj,   TOVAR K OBJEDNANIU NA OBCHODNOM ODDELENÍ' AS old_text, 'bezpečnostná obuv S2, ochranná oceľová špica, protiprepichová oceľová stielka, Tunnel system®, E - absorpcia energie v oblasti päty, SRA - protišmyková podošva - duálny PU, CI, HI - izolácia proti chladu aj teplu, FO - odolná voči palivovému oleju, A - antistatická, ESD - odvádza elektrostatický náboj,   TOVAR K OBJEDNANIU NA OBCHODNOM ODDELENÍ' AS new_text
  UNION ALL SELECT 'AP718119', '<p>Akrylátový prívesok na kľúče s plnofarebnou potlačou. Tvar na zakázku - max. rozmer 45 x 45 mm. Cena zahŕňa UV LED tlač na 1 strane. Min. mn.: 250 ks.</p>', '<p>Akrylátový prívesok na kľúče s plnofarebnou potlačou. Tvar na zákazku - max. rozmer 45 x 45 mm. Cena zahŕňa UV LED tlač na 1 strane. Min. mn.: 250 ks.</p>'
  UNION ALL SELECT 'AP718506', '<p>Taška ze sulfátového papiera s plochými uškami, 90 g/m².</p>', '<p>Taška zo sulfátového papiera s plochými uškami, 90 g/m².</p>'
  UNION ALL SELECT 'AP718509', '<p>Taška ze sulfátového papiera s plochými uškami, 70 g/m².</p>', '<p>Taška zo sulfátového papiera s plochými uškami, 70 g/m².</p>'
  UNION ALL SELECT 'AP731504', '<p>Ohybná ceruzka s gumou. Vyrobená zo špeciálneho ohybného plastu. Dodáva se nezastrúhaná.</p>', '<p>Ohybná ceruzka s gumou. Vyrobená zo špeciálneho ohybného plastu. Dodáva sa nezastrúhaná.</p>'
  UNION ALL SELECT 'AP791916', '<p>Ceruzka z prírodného dreva s farebnou gumou. Dodáva se nezastrúhaná.</p>', '<p>Ceruzka z prírodného dreva s farebnou gumou. Dodáva sa nezastrúhaná.</p>'
  UNION ALL SELECT 'AP862009', '<p>Cană ceramică albă cu interior colorat, 350 ml. Culoarea logo-ul gravat se potrivește cu culoarea interiorului. In cutie individuală.</p>', '<p>Biely keramický hrnček s farebným vnútrom, 350 ml. Farba gravírovaného loga ladí s farbou vnútra. V samostatnej krabičke.</p>'
  UNION ALL SELECT 'AP809479', '<p>Hliníková sada kuličkového pera a mechanické tužky trojuholníkové tvaru v černé dárkové krabičce. Modrá náplň, 0,7 mm tuhy.</p>', '<p>Hliníková sada guľôčkového pera a mechanickej ceruzky trojuholníkového tvaru v čiernej darčekovej krabičke. Modrá náplň, tuha 0,7 mm.</p>'
  UNION ALL SELECT 'AP809353', '<p>Stolný držiak na pero so 4-portovým rozbočovačom USB a modrým svetlom, USB 2.0., materiál: MATERIÁL: ABS. Medzi 2 steny možno umiestniť vlastnú grafiku s potlačou.</p>', '<p>Stolný držiak na perá so 4-portovým USB hubom a modrým svetlom, USB 2.0, materiál: ABS. Medzi 2 steny možno vložiť vlastnú potlačenú grafiku.</p>'
  UNION ALL SELECT 'AP718189', '<p>Recyklované papierové guličkové pero s preglejkovým klipom vyrobeným na zákazku a modrou náplňou. Klip je vyrobený na zákazku - maximálny rozmer: 25×35 mm. Cena vrátane gravírovania loga na klip, nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>', '<p>Recyklované papierové guľôčkové pero s preglejkovým klipom vyrobeným na zákazku a modrou náplňou. Klip je vyrobený na zákazku - maximálny rozmer: 25×35 mm. Cena vrátane gravírovania loga na klip, nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>'
  UNION ALL SELECT 'AP721468', '<p>Hřeben z ekologického plastu z pšeničné slámy.</p>', '<p>Hrebeň z ekologického plastu z pšeničnej slamy.</p>'
  UNION ALL SELECT 'AP718395', '<p>Praktické papierové skladacie púzdro pre jednorázové rúško. Cena zahŕňa plnofarebnú potlač na prednej strane, nezahŕňa tlačovú prípravu. Min. množstvo 250 ks.</p>', '<p>Praktické papierové skladacie puzdro pre jednorázové rúško. Cena zahŕňa plnofarebnú potlač na prednej strane, nezahŕňa tlačovú prípravu. Min. množstvo 250 ks.</p>'
  UNION ALL SELECT 'AP718558', '<p>Na zákazku vyrábané púzdro na okuliare zo softshellu, s celoplošne tlačenou grafikou v cene, 95% polyester, 5% elastan. Cena nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>', '<p>Na zákazku vyrábané puzdro na okuliare zo softshellu, s celoplošne tlačenou grafikou v cene, 95% polyester, 5% elastan. Cena nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>'
  UNION ALL SELECT 'AP722028', '<p>Ekologické plastové guličkové pero z pšeničnej slamy s modrou náplňou.</p>', '<p>Ekologické plastové guľôčkové pero z pšeničnej slamy s modrou náplňou.</p>'
  UNION ALL SELECT 'AP722607', '<p>RPET poudro na pera s bambusovým víčkem a elastickým páskem. S pravítkem a integrovaným držákem mobilního telefonu.</p>', '<p>RPET puzdro na perá s bambusovým viečkom a elastickým pásikom. S pravítkom a integrovaným držiakom na mobilný telefón.</p>'
  UNION ALL SELECT 'AP716629', '<p>Na zakázku vyrobený plstěný batoh z RPET rolovací klopy s jednou vnitřní částí a celobarevně potištěnou přední kapsou. S výrazným štítkem RPET. Cena včetně sublimačního tisku, nezahrnuje tiskovou přípravu. Min. mn.: 25 ks.</p>', '<p>Plstený ruksak z RPET s rolovacou klopou vyrobený na zákazku, s jednou vnútornou priehradkou a plnofarebne potlačeným predným vreckom. S výrazným štítkom RPET. Cena zahŕňa sublimačnú potlač, nezahŕňa tlačovú prípravu. Min. mn.: 25 ks.</p>'
  UNION ALL SELECT 'AP800504', '<p>Ekologické plastové guličkové pero z pšeničnej slamy s bambusovým úchopom a kovovými časťami. S modrou náplňou.</p>', '<p>Ekologické plastové guľôčkové pero z pšeničnej slamy s bambusovým úchopom a kovovými časťami. S modrou náplňou.</p>'
