  UNION ALL SELECT 'AP733356', '<p>Ekologické plastové guličkové pero z pšeničnej slamy s puzdrom potiahnutým prírodným korkom. So 4 farebnými náplňami: čierna, modrá, zelená a červená.</p>', '<p>Ekologické plastové guľôčkové pero z pšeničnej slamy s puzdrom potiahnutým prírodným korkom. So 4 farebnými náplňami: čierna, modrá, zelená a červená.</p>'
  UNION ALL SELECT 'AP733849', '<p>Plastové otočné guličkové pero a dotykové pero so vstavanou sadou na čistenie slúchadiel. S modrou náplňou.</p>', '<p>Plastové otočné guľôčkové pero a dotykové pero so vstavanou sadou na čistenie slúchadiel. S modrou náplňou.</p>'
  UNION ALL SELECT 'AP800544', '<p>Kovový púzdro na vizitky potiahnuté bambusom.</p>', '<p>Kovové puzdro na vizitky potiahnuté bambusom.</p>'
  UNION ALL SELECT 'AP808138', '<p>Drevené guličkové pero so štvorcovým tubusom a 14 cm pravítkom na jednej strane. S čiernou náplňou.</p>', '<p>Drevené guľôčkové pero so štvorcovým tubusom a 14 cm pravítkom na jednej strane. S čiernou náplňou.</p>'
  UNION ALL SELECT 'AP716852', '<p>Na zákazku vyrobené púzdro na mobilný telefón z RPET neoprénu. Vhodné pre mobilné telefóny s uhlopriečkou displeja až 6 palcov.</p>', '<p>Na zákazku vyrobené puzdro na mobilný telefón z RPET neoprénu. Vhodné pre mobilné telefóny s uhlopriečkou displeja až 6 palcov.</p>'
  UNION ALL SELECT 'AP808186', '<p>Bambusové guličkové pero s priehľadnou hornou časťou a chrómovými detailmi.</p>', '<p>Bambusové guľôčkové pero s priehľadnou hornou časťou a chrómovými detailmi.</p>'
  UNION ALL SELECT 'AP716858', '<p>Na zákazku vyrobené púzdro na perá so zipsom v tvare obdĺžnika z polyesteru 600D RPET. S celoplošne tlačenou sublimačnou grafikou a výrazným štítkom RPET. Cena nezahŕňa tlačovú prípravu. Min.mn.: 50 ks.</p>', '<p>Na zákazku vyrobené puzdro na perá so zipsom v tvare obdĺžnika z polyesteru 600D RPET. S celoplošne tlačenou sublimačnou grafikou a výrazným štítkom RPET. Cena nezahŕňa tlačovú prípravu. Min.mn.: 50 ks.</p>'
  UNION ALL SELECT 'AP716946', '<p>Taška cez rameno vyrobené na zákazku z 600D RPET polyesteru s dlhým ramenným popruhom a zapínaním na gombík. S celoplošným sublimačným potiskom a výrazným RPET štítkom. Cena nezahrnuje tlačovú prípravu. Min. min.: 25 ks.</p>', '<p>Taška cez rameno vyrobená na zákazku z 600D RPET polyesteru s dlhým ramenným popruhom a zapínaním na gombík. S celoplošnou sublimačnou potlačou a výrazným štítkom RPET. Cena nezahŕňa tlačovú prípravu. Min. mn.: 25 ks.</p>'
  UNION ALL SELECT 'AP716920', '<p>Pexeso z laminovanej březové prekližky na zákazku s vlastnou grafikou v bavlnenom pytlíku. S 24 dlaždicami (ø35 mm). Cena zahŕňa 12 rôznych plnofarebných potiskov na prednej strane dlaždice a identický plnofarebný potisk na zadnej strane všetkých dlaždic, nezahrnuje tlačovú prípravu. Min. min.: 50 ks.</p>', '<p>Pexeso z laminovanej brezovej preglejky na zákazku s vlastnou grafikou v bavlnenom vrecku. S 24 kartičkami (ø35 mm). Cena zahŕňa 12 rôznych plnofarebných potlačí na prednej strane kartičiek a rovnakú plnofarebnú potlač na zadnej strane všetkých kartičiek, nezahŕňa tlačovú prípravu. Min. mn.: 50 ks.</p>'
  UNION ALL SELECT 'AP716936', '<p>6 ks žvýkaček bez cukru v blistri na zákazku, s farebným potištěným perforovaným kraftovým papierovým obalom. Cena nezahrnuje tlačovú prípravu. Min. min.: 100 ks.</p>', '<p>6 ks žuvačiek bez cukru v blistri na zákazku, s farebne potlačeným perforovaným obalom z kraftového papiera. Cena nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>'
  UNION ALL SELECT 'AP716943', '<p>6 ks žvýkaček bez cukru v blistri na zákazku, s farebným potištěným perforovaným papierovým obalem. Cena nezahrnuje tlačovú prípravu. Min. min.: 100 ks.</p>', '<p>6 ks žuvačiek bez cukru v blistri na zákazku, s farebne potlačeným perforovaným papierovým obalom. Cena nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>'
  UNION ALL SELECT 'AP716961', '<p>Kapesní papírový kalendář (270 g/m²) na zakázku s plnobarevnou grafikou. Cena zahrnuje digitální tisk na obou stranách, nezahrnuje tiskovou přípravu. Min. min.: 250 ks</p>', '<p>Vreckový papierový kalendár (270 g/m²) na zákazku s plnofarebnou grafikou. Cena zahŕňa digitálnu tlač na oboch stranách, nezahŕňa tlačovú prípravu. Min. mn.: 250 ks.</p>'
  UNION ALL SELECT 'AP716964', '<p>5 ks veľkých mátových bonbónov v blistri na zákazku, s farebným potištěným papírovým obalem. Cena nezahrnuje tlačovú prípravu. Min. min.: 100 ks.</p>', '<p>5 ks veľkých mätových cukríkov v blistri na zákazku, s farebne potlačeným papierovým obalom. Cena nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>'
  UNION ALL SELECT 'AP716965', '<p>5 ks veľkých mátových bonbónov na zákazku, s farebným potištěným kraftovým papierovým obalem. Cena nezahrnuje tlačovú prípravu. Min. min.: 100 ks.</p>', '<p>5 ks veľkých mätových cukríkov na zákazku, s farebne potlačeným obalom z kraftového papiera. Cena nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>'
  UNION ALL SELECT 'AP716966', '<p>10 ks veľkých matových bonbónov v blistri na zákazku, s farebne potištěnou papírovou krabičkou. Cena nezahrnuje tlačovú prípravu. Min. min.: 100 ks.</p>', '<p>10 ks veľkých mätových cukríkov v blistri na zákazku, s farebne potlačenou papierovou krabičkou. Cena nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>'
  UNION ALL SELECT 'AP716967', '<p>10 ks veľkých mátových bonbónov v blistri na zákazku, s plnofarebnou potištěnou kraftovou papírovou krabičkou. Cena nezahrnuje tlačovú prípravu. Min. min.: 100 ks.</p>', '<p>10 ks veľkých mätových cukríkov v blistri na zákazku, s plnofarebne potlačenou krabičkou z kraftového papiera. Cena nezahŕňa tlačovú prípravu. Min. mn.: 100 ks.</p>'
  UNION ALL SELECT 'AP864103', '<p>Sada 2 dobíjacích COB svetiel na kolo s plastovým puzdrom, vstavanou dobíjacou batériami cez USB (100 mAh) a elastickými montážnymi popruhmi. Se 3 režimami svietenia. Včetne nabíjacieho kábla cez USB. Nepredajné v nasledujúcich krajinách: Nemecko, Rakúsko, Švajčiarsko.</p>', '<p>Sada 2 dobíjacích COB svetiel na bicykel s plastovým puzdrom, vstavanou batériou dobíjateľnou cez USB (100 mAh) a elastickými montážnymi popruhmi. S 3 režimami svietenia. Vrátane nabíjacieho kábla USB. Nepredajné v týchto krajinách: Nemecko, Rakúsko, Švajčiarsko.</p>'
  UNION ALL SELECT 'AP800295', '<p>Šesťhranné guličkové pero z recyklovaného hliníka s bambusovým tlačidlom a chrómovanými časťami. S modrou náplňou.</p>', '<p>Šesťhranné guľôčkové pero z recyklovaného hliníka s bambusovým tlačidlom a chrómovanými časťami. S modrou náplňou.</p>'
  UNION ALL SELECT 'AP800291', '<p>Súprava púzdra na pás a visačky na batožinu z recyklovanej umelej kože. V krabičke z kraftového papiera.</p>', '<p>Súprava puzdra na pás a visačky na batožinu z recyklovanej umelej kože. V krabičke z kraftového papiera.</p>'
  UNION ALL SELECT 'AP757019', '<p>Súprava na pestovanie vianočného stromčeka v obale z kraftového papiera. Obsahuje kapsulu so semienkami smreka ztepilého (Picea abies), rašelinový disk a papierový kvetináč.</p>', '<p>Súprava na pestovanie vianočného stromčeka v obale z kraftového papiera. Obsahuje kapsulu so semienkami smreka obyčajného (Picea abies), rašelinový disk a papierový kvetináč.</p>'
  UNION ALL SELECT 'AP800845', '<p>Dvojdielna darčeková sada písacích potrieb v papierovej darčekovej krabičke. Obsahuje poznámkový blok formátu A5 s doskami z recyklovanej PU kože, štítkom pre logo v ružovo zlatej farbe a 80 linajkovými listami z recyklovaného papiera. Súčasťou je aj guličkové pero z recyklovaného hliníka s detailmi v ružovo zlatej farbe a povrchovou úpravou vhodnou na zrkadlové gravírovanie. S modrou náplňou.</p>', '<p>Dvojdielna darčeková sada písacích potrieb v papierovej darčekovej krabičke. Obsahuje poznámkový blok formátu A5 s doskami z recyklovanej PU kože, štítkom pre logo v ružovo zlatej farbe a 80 linajkovými listami z recyklovaného papiera. Súčasťou je aj guľôčkové pero z recyklovaného hliníka s detailmi v ružovo zlatej farbe a povrchovou úpravou vhodnou na zrkadlové gravírovanie. S modrou náplňou.</p>'
  UNION ALL SELECT 'AP800846', '<p>Dvojdielna darčeková sada písacích potrieb v papierovej darčekovej krabičke. Obsahuje poznámkový blok formátu A5 s doskami z recyklovanej PU kože, štítkom pre logo v ružovo zlatej farbe a 80 linajkovými listami z recyklovaného papiera. Súčasťou je aj guličkové pero z recyklovaného hliníka s detailmi v ružovo zlatej farbe a povrchovou úpravou vhodnou na zrkadlové gravírovanie. S modrou náplňou.</p>', '<p>Dvojdielna darčeková sada písacích potrieb v papierovej darčekovej krabičke. Obsahuje poznámkový blok formátu A5 s doskami z recyklovanej PU kože, štítkom pre logo v ružovo zlatej farbe a 80 linajkovými listami z recyklovaného papiera. Súčasťou je aj guľôčkové pero z recyklovaného hliníka s detailmi v ružovo zlatej farbe a povrchovou úpravou vhodnou na zrkadlové gravírovanie. S modrou náplňou.</p>'
  UNION ALL SELECT 'AP800813', '<p>Trojdielna darčeková sada v darčekovej krabičke z kraftového papiera s produktmi doplnenými detailmi z prírodného korku. Obsahuje poznámkový blok formátu A5 s obalom z recyklovanej PU kože a 80 linajkovými listami z recyklovaného papiera, dvojstennú vákuovo izolovanú fľašu s objemom 500 ml z recyklovanej nerezovej ocele (90 % recyklovaného materiálu) a guličkové pero z recyklovaného hliníka s modrou náplňou.</p>', '<p>Trojdielna darčeková sada v darčekovej krabičke z kraftového papiera s produktmi doplnenými detailmi z prírodného korku. Obsahuje poznámkový blok formátu A5 s obalom z recyklovanej PU kože a 80 linajkovými listami z recyklovaného papiera, dvojstennú vákuovo izolovanú fľašu s objemom 500 ml z recyklovanej nerezovej ocele (90 % recyklovaného materiálu) a guľôčkové pero z recyklovaného hliníka s modrou náplňou.</p>'
  UNION ALL SELECT 'AP800849', '<p>Dvojdielna darčeková sada kancelárskych potrieb v papierovej darčekovej krabičke. Obsahuje poznámkový blok formátu A5 s doskami z recyklovanej PU kože, elastickou gumičkou a záložkou v metalickom prevedení a 80 linkovanými listami z recyklovaného papiera. Súčasťou je aj guličkové pero z recyklovaného hliníka s pogumovaným povrchom, lesklými metalickými detailmi a povrchovou úpravou vhodnou na zrkadlové gravírovanie. S modrou náplňou.</p>', '<p>Dvojdielna darčeková sada kancelárskych potrieb v papierovej darčekovej krabičke. Obsahuje poznámkový blok formátu A5 s doskami z recyklovanej PU kože, elastickou gumičkou a záložkou v metalickom prevedení a 80 linkovanými listami z recyklovaného papiera. Súčasťou je aj guľôčkové pero z recyklovaného hliníka s pogumovaným povrchom, lesklými metalickými detailmi a povrchovou úpravou vhodnou na zrkadlové gravírovanie. S modrou náplňou.</p>'
  UNION ALL SELECT 'AP800859', '<p>Trojdielna business darčeková sada v papierovej darčekovej krabičke. Obsahuje produkty potiahnuté recyklovaným polyesterom RPET s kovovými detailmi v zodpovedajúcej farbe. Súčasťou je guličkové pero z recyklovaného hliníka s modrou náplňou, kovové puzdro na vizitky a kovový prívesok na kľúče.</p>', '<p>Trojdielna business darčeková sada v papierovej darčekovej krabičke. Obsahuje produkty potiahnuté recyklovaným polyesterom RPET s kovovými detailmi v zodpovedajúcej farbe. Súčasťou je guľôčkové pero z recyklovaného hliníka s modrou náplňou, kovové puzdro na vizitky a kovový prívesok na kľúče.</p>'
) t ON t.ref COLLATE utf8mb4_bin = p.reference COLLATE utf8mb4_bin
SET pl.description = t.new_text
WHERE pl.description COLLATE utf8mb4_bin = t.old_text COLLATE utf8mb4_bin;

UPDATE ps_product_lang pl
JOIN ps_lang l ON l.id_lang = pl.id_lang AND l.iso_code = 'sk'
JOIN ps_product p ON p.id_product = pl.id_product
JOIN (
  SELECT 'B32' AS ref, 'Svrchní materiál - broušená voděodolná kůže (nubuk), síťovina, podšívka - Cool Comfort®' AS old_text, 'Zvršok - brúsená vodoodolná koža (nubuk), sieťovina, podšívka - Cool Comfort®' AS new_text
) t ON t.ref COLLATE utf8mb4_bin = p.reference COLLATE utf8mb4_bin
SET pl.description_short = t.new_text
WHERE pl.description_short COLLATE utf8mb4_bin = t.old_text COLLATE utf8mb4_bin;

